   "	highp float hr  = radians(jmh.z);\n"
   "	highp vec3  aab = vec3(pow(jmh.x * 0.01, sc.z), jmh.y * cos(hr), jmh.y * sin(hr));\n"
   "	highp vec3  a   = aab_to_cone * aab;\n"
   "	return to_rgb * vec3(dt_cone_inv(a.x), dt_cone_inv(a.y), dt_cone_inv(a.z));\n"
   "}\n"
   "\n"
   "highp float dt_j_to_y(highp float J, highp vec4 sc)\n"
   "{\n"
   "	return dt_cone_inv(sc.w * pow(abs(J) * 0.01, sc.z)) / sc.x;\n"
   "}\n"
   "\n"
   "highp float dt_y_to_j(highp float Y, highp vec4 sc)\n"
   "{\n"
   "	highp float J = 100.0 * pow(dt_cone_fwd(abs(Y) * sc.x) / sc.w, sc.y);\n"
   "	return Y < 0.0 ? -J : J;\n"
   "}\n"
   "\n"
   "highp float dt_ts_fwd(highp float x)\n"
   "{\n"
   "	highp float f = dt.ts.x * pow(max(x, 0.0) / (x + dt.ts.y), dt.ts.z);\n"
   "	return max(f * f / (f + dt.ts.w), 0.0) * 100.0;\n"
   "}\n"
   "\n"
   "highp float dt_cc_norm(highp float h)\n"
   "{\n"
   "	highp float hr = radians(h);\n"
   "	highp float a = cos(hr), b = sin(hr);\n"
   "	highp float c2 = a * a - b * b, s2 = 2.0 * a * b;\n"
   "	highp float c3 = 4.0 * a * a * a - 3.0 * a, s3 = 3.0 * b - 4.0 * b * b * b;\n"
   "	return (11.34072 * a + 16.46899 * c2 + 7.88380 * c3 + 14.66441 * b\n"
   "	        - 6.37224 * s2 + 9.19364 * s3 + 77.12896) * dt.cc2.y;\n"
   "}\n"
   "\n"
   "highp float dt_toe_fwd(highp float x, highp float limit, highp float k1in, highp float k2in)\n"
   "{\n"
   "	highp float k2, k1, k3, mb, mc;\n"
   "	if (x > limit)\n"
   "		return x;\n"
   "	k2 = max(k2in, 0.001);\n"
   "	k1 = sqrt(k1in * k1in + k2 * k2);\n"
   "	k3 = (limit + k1) / (limit + k2);\n"
   "	mb = k3 * x - k1;\n"
   "	mc = k2 * k3 * x;\n"
   "	return 0.5 * (mb + sqrt(mb * mb + 4.0 * mc));\n"
   "}\n"
   "\n"
   "highp vec4 dt_lut_at(highp float h)\n"
   "{\n"
   "	highp float u = (mod(h, 360.0) + 0.5) / 360.0;\n"
   "	return texture(uDtAces2Lut, vec2(u, 0.5)) * dt.lutScale;\n"
   "}\n"
   "\n"
   "highp vec3 dt_chroma_compress(highp vec3 jmh, highp float tmJ, highp vec4 lut)\n"
   "{\n"
   "	highp float nJ, snJ, Mn, limit, M;\n"
   "	if (jmh.y == 0.0)\n"
   "		return vec3(tmJ, 0.0, jmh.z);\n"
   "	nJ    = tmJ / dt.cc.x;\n"
   "	snJ   = max(0.0, 1.0 - nJ);\n"
   "	Mn    = dt_cc_norm(jmh.z);\n"
   "	limit = pow(nJ, dt.cc.y) * lut.z / Mn;\n"
   "	M     = jmh.y * pow(tmJ / jmh.x, dt.cc.y) / Mn;\n"
   "	M     = limit - dt_toe_fwd(limit - M, limit - 0.001, snJ * dt.cc.z, sqrt(nJ * nJ + dt.cc.w));\n"
   "	M     = dt_toe_fwd(M, limit, nJ * dt.cc2.x, snJ);\n"
   "	return vec3(tmJ, M * Mn, jmh.z);\n"
   "}\n"
   "\n"
   "highp float dt_focus_gain(highp float J, highp float athr)\n"
   "{\n"
   "	highp float gain = dt.cc.x * dt.cc2.w;\n"
   "	if (J > athr)\n"
   "	{\n"
   "		highp float adj = log(max(dt.cc.x - athr, 1e-6) / max(dt.cc.x - J, 0.0001)) / log(10.0);\n"
   "		gain *= adj * adj + 1.0;\n"
   "	}\n"
   "	return gain;\n"
   "}\n"
   "\n"
   "highp float dt_solve_j(highp float J, highp float M, highp float fJ, highp float sg)\n"
   "{\n"
   "	highp float Ms = M / sg, a = Ms / fJ, b, c;\n"
   "	if (J < fJ)\n"
   "	{\n"
   "		b = 1.0 - Ms;\n"
   "		c = -J;\n"
   "		return -2.0 * c / (b + sqrt(b * b - 4.0 * a * c));\n"
   "	}\n"
   "	b = -(1.0 + Ms + dt.cc.x * a);\n"
   "	c = dt.cc.x * Ms + J;\n"
   "	return -2.0 * c / (b - sqrt(b * b - 4.0 * a * c));\n"
   "}\n"
   "\n"
   "highp float dt_vec_slope(highp float iJ, highp float fJ, highp float sg)\n"
   "{\n"
   "	highp float d = (iJ < fJ) ? iJ : (dt.cc.x - iJ);\n"
   "	return d * (iJ - fJ) / (fJ * sg);\n"
   "}\n"
   "\n"
   "highp float dt_smin(highp float a, highp float b, highp float ref)\n"
   "{\n"
   "	highp float s  = 0.12 * ref;\n"
   "	highp float hh = max(s - abs(a - b), 0.0) / s;\n"
   "	return min(a, b) - hh * hh * hh * s / 6.0;\n"
   "}\n"
   "\n"
   "highp float dt_bound_m(highp float iJ, highp float slope, highp float ig,\n"
   "                       highp float Jm, highp float Mm, highp float Jr)\n"
   "{\n"
   "	return Jr * pow(iJ / Jr, ig) * Mm / (Jm - slope * Mm);\n"
   "}\n"
   "\n"
   "highp vec3 dt_gamut_compress(highp vec3 jmh, highp vec4 lut)\n"
   "{\n"
   "	highp float blend, fJ, athr, sg, iJ, slope, iJc, lower, upper, gb, rb, prop, thr, M;\n"
   "	if (jmh.x <= 0.0)\n"
   "		return vec3(0.0, 0.0, jmh.z);\n"
   "	if (jmh.y < 0.0 || jmh.x > dt.cc.x)\n"
   "		return vec3(jmh.x, 0.0, jmh.z);\n"
   "	blend = min(1.3 - lut.x / dt.cc.x, 1.0);\n"
   "	fJ    = lut.x + (dt.cc2.z - lut.x) * blend;\n"
   "	athr  = lut.x + (dt.cc.x - lut.x) * 0.3;\n"
   "	sg    = dt_focus_gain(jmh.x, athr);\n"
   "	iJ    = dt_solve_j(jmh.x, jmh.y, fJ, sg);\n"
   "	slope = dt_vec_slope(iJ, fJ, sg);\n"
   "	iJc   = dt_solve_j(lut.x, lut.y, fJ, sg);\n"
   "	lower = dt_bound_m(iJ, slope, dt.gm.x, lut.x, lut.y, iJc);\n"
   "	upper = dt_bound_m(dt.cc.x - iJ, -slope, lut.w, dt.cc.x - lut.x, lut.y, dt.cc.x - iJc);\n"
   "	gb    = dt_smin(lower, upper, lut.y);\n"
   "	if (gb <= 0.0)\n"
   "		return vec3(jmh.x, 0.0, jmh.z);\n"
   "	rb    = dt_bound_m(iJ, slope, dt.cc.y, dt.cc.x, lut.z, dt.cc.x);\n"
   "	prop  = max(gb / rb, 0.75);\n"
   "	thr   = prop * gb;\n"
   "	M     = jmh.y;\n"
   "	if (!(M <= thr || prop >= 1.0))\n"
   "	{\n"
   "		highp float mo = M - thr, go = gb - thr, ro = rb - thr;\n"
   "		highp float scale = ro / ((ro / go) - 1.0);\n"
   "		highp float nd = mo / scale;\n"
   "		M = thr + scale * nd / (1.0 + nd);\n"
   "	}\n"
   "	return vec3(iJ + M * slope, M, jmh.z);\n"
   "}\n"
   "\n"
   "/* Rec.709 (D65) linear -> ACES2065-1 (AP0, D60), Bradford adapted: the\n"
   " * transform's input space. Column-major. */\n"
   "const highp mat3 DT_709_TO_AP0 = mat3(\n"
   "	0.4397010, 0.0897923, 0.0175440,\n"
   "	0.3829780, 0.8134230, 0.1115440,\n"
   "	0.1773350, 0.0967616, 0.8707040);\n"
   "\n"
   "highp vec3 dt_clamp_ap0_to_ap1(highp vec3 aces, highp float upper)\n"
   "{\n"
   "	const highp mat3 to_ap1 = mat3( 1.4514393161, -0.0765537733,  0.0083161484,\n"
   "	                               -0.2365107469,  1.1762296998, -0.0060324498,\n"
   "	                               -0.2149285693, -0.0996759265,  0.9977163014);\n"
   "	const highp mat3 to_ap0 = mat3( 0.6954522414,  0.0447945634, -0.0055258826,\n"
   "	                                0.1406786965,  0.8596711185,  0.0040252103,\n"
   "	                                0.1638690622,  0.0955343182,  1.0015006723);\n"
   "	return to_ap0 * clamp(to_ap1 * aces, 0.0, upper);\n"
   "}\n"
   "\n"
   "/* Scene Rec.709 (1.0 = paper white) -> limiting primaries (1.0 = 100 nits). */\n"
   "highp vec3 dt_aces2(highp vec3 v)\n"
   "{\n"
   "	highp vec3  aces = dt_clamp_ap0_to_ap1(DT_709_TO_AP0 * v * dt.film.w, dt.gm.y);\n"
   "	highp vec3  jmh  = dt_rgb_to_jmh(aces, dt.inRgbToCam, dt.inConeToAab, dt.inScalars);\n"
   "	highp float tmJ  = dt_y_to_j(dt_ts_fwd(dt_j_to_y(jmh.x, dt.inScalars) * 0.01), dt.inScalars);\n"
   "	highp vec3  tm   = dt_chroma_compress(jmh, tmJ, dt_lut_at(jmh.z));\n"
   "	highp vec3  cg   = dt_gamut_compress(tm, dt_lut_at(tm.z));\n"
   "	return dt_jmh_to_rgb(cg, dt.limAabToCone, dt.limCamToRgb, dt.limScalars);\n"
   "}\n"
   "\n"
   "/* ---- the curves on the whole colour ---- */\n"
   "highp vec3 dt_aces_fit_rrt(highp vec3 v)\n"
   "{\n"
   "	highp vec3 a = v * (v + 0.0245786) - 0.000090537;\n"
   "	highp vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081;\n"
   "	return a / b;\n"
   "}\n"
   "\n"
   "highp vec3 dt_curve_rgb(highp vec3 c)\n"
   "{\n"
   "	int m = int(dt.mode.x + 0.5);\n"
   "	if (m == 22)        /* AgX */\n"
   "	{\n"
   "		const highp mat3 mi = mat3(0.842479062253094, 0.0784335999999992, 0.0792237451477643,\n"
   "		                           0.0423282422610123, 0.878468636469772, 0.0791661274605434,\n"
   "		                           0.0423756549057051, 0.0784336, 0.879142973793104);\n"
   "		const highp mat3 mo = mat3(1.19687900512017, -0.0980208811401368, -0.0990297440797205,\n"
   "		                           -0.0528968517574562, 1.15190312990417, -0.0989611768448433,\n"
   "		                           -0.0529716355144438, -0.0980434501171241, 1.15107367264116);\n"
   "		highp vec3 v = mi * max(c, vec3(0.0));\n"
   "		highp vec3 v2, v4;\n"
   "		v  = clamp((log2(max(v, vec3(1e-10))) + 12.47393) / 16.500009, 0.0, 1.0);\n"
   "		v2 = v * v;\n"
   "		v4 = v2 * v2;\n"
   "		v  = 15.5 * v4 * v2 - 40.14 * v4 * v + 31.96 * v4\n"
   "		   - 6.868 * v2 * v + 0.4298 * v2 + 0.1191 * v - 0.00232;\n"
   "		v  = pow(max(mo * v, vec3(0.0)), vec3(2.2)) * 1.4491792;\n"
   "		if (dt.sh.w > 0.5)  /* Punchy: contrast 1.35, saturation 1.4 */\n"
   "		{\n"
   "			highp vec3  u = pow(v, vec3(1.35));\n"
   "			highp float n = dot(u, vec3(0.2126, 0.7152, 0.0722));\n"
   "			v = max(vec3(n) + (u - vec3(n)) * 1.4, vec3(0.0));\n"
   "		}\n"
   "		return v;\n"
   "	}\n"
   "	if (m == 21)        /* Khronos PBR Neutral */\n"
   "	{\n"
   "		highp float x   = min(c.r, min(c.g, c.b));\n"
   "		highp float off = x < 0.08 ? x - 6.25 * x * x : 0.04;\n"
   "		highp vec3  v   = c - off;\n"
   "		highp float peak = max(v.r, max(v.g, v.b));\n"
   "		highp float d, np, g;\n"
   "		if (peak < 0.76)\n"
   "			return v * 1.1506276;\n"
   "		d  = 1.0 - 0.76;\n"
   "		np = 1.0 - d * d / (peak + d - 0.76);\n"
   "		v *= np / peak;\n"
   "		g  = 1.0 - 1.0 / (0.15 * (peak - np) + 1.0);\n"
   "		return mix(v, vec3(np), g) * 1.1506276;\n"
   "	}\n"
   "	if (m == 18)        /* Filmic Log (Sobotka): desaturation cube, contrast curve */\n"
   "	{\n"
   "		highp vec3  t = clamp((log2(max(c, vec3(1e-10))) + 12.4739312) * 0.04, 0.0, 1.0);\n"
   "		highp vec3  d = t * 32.0;\n"
   "		highp float bz = floor(d.z), fz = d.z - bz;\n"
   "		highp vec2  uv = vec2((bz * 33.0 + min(d.x, 31.999) + 0.5) / 1089.0, (d.y + 0.5) / 33.0);\n"
   "		highp vec3  s0 = texture(uDtFilmDesat, uv).rgb;\n"
   "		highp vec3  s1 = texture(uDtFilmDesat, uv + vec2(33.0 / 1089.0, 0.0)).rgb;\n"
   "		highp vec3  o;\n"
   "		t   = clamp(mix(s0, s1, fz) * dt.film.x, 0.0, 1.0);\n"
   "		o.r = texture(uDtFilmLut, vec2(t.r, 0.5)).r;\n"
   "		o.g = texture(uDtFilmLut, vec2(t.g, 0.5)).r;\n"
   "		o.b = texture(uDtFilmLut, vec2(t.b, 0.5)).r;\n"
   "		return pow(max(o, vec3(0.0)), vec3(2.2)) * dt.film.y;\n"
   "	}\n"
   "	if (m == 20)        /* ACES Fitted (Hill) */\n"
   "	{\n"
   "		const highp mat3 mi = mat3(0.59719, 0.07600, 0.02840,\n"
   "		                           0.35458, 0.90834, 0.13383,\n"
   "		                           0.04823, 0.01566, 0.83777);\n"
   "		const highp mat3 mo = mat3( 1.60475, -0.10208, -0.00327,\n"
   "		                           -0.53108,  1.10813, -0.07276,\n"
   "		                           -0.07367, -0.00605,  1.07602);\n"
   "		return max(mo * dt_aces_fit_rrt(mi * c), vec3(0.0)) * 1.6152077;\n"
   "	}\n"
   "	{                   /* 19: Reinhard-Jodie */\n"
   "		highp float l  = dot(c, vec3(0.2126, 0.7152, 0.0722));\n"
   "		highp vec3  tv = c / (1.0 + c);\n"
   "		return mix(c / (1.0 + l), tv, tv) * 2.0;\n"
   "	}\n"
   "}\n"
   "\n"
   "/* ---- the per-channel curves ---- */\n"
   "highp float dt_curve(highp float v)\n"
   "{\n"
   "	int m = int(dt.mode.x + 0.5);\n"
   "	highp float x = max(v, 0.0);\n"
   "	if (m == 1)         /* ACES (Narkowicz) */\n"
   "		return dt_shoulder(v, v * (2.51 * v + 0.03) / (v * (2.43 * v + 0.59) + 0.14) * 1.2440945);\n"
   "	if (m == 2)         /* Hejl and Burgess-Dawson */\n"
   "	{\n"
   "		highp float h = max(v - 0.004, 0.0);\n"
   "		return dt_shoulder(v, pow((h * (6.2 * h + 0.5)) / (h * (6.2 * h + 1.7) + 0.06), 2.2) * 1.4629683);\n"
   "	}\n"
   "	if (m == 3)         /* GT (Uchimura) */\n"
   "	{\n"
   "		highp float t  = clamp(v / dt.gt.x, 0.0, 1.0);\n"
   "		highp float w0 = 1.0 - (t * t * (3.0 - 2.0 * t));\n"
   "		highp float w2 = step(dt.gt.y, v);\n"
   "		highp float w1 = 1.0 - w0 - w2;\n"
   "		highp float T  = dt.gt.x * pow(x / dt.gt.x, 1.33);\n"
   "		highp float S  = 1.0 - dt.gt.z * exp(-dt.gt.w * (v - dt.gt.y));\n"
   "		return (T * w0 + v * w1 + S * w2) * dt.sh.z;\n"
   "	}\n"
   "	if (m == 4)         /* Hable (Uncharted 2) */\n"
   "		return dt_shoulder(v, (((v * (0.15 * v + 0.05) + 0.004) / (v * (0.15 * v + 0.50) + 0.06))\n"
   "		                       - 0.0666667) * 4.5319149);\n"
   "	if (m == 5)         /* Lottes */\n"
   "		return dt_shoulder(v, (pow(x, 1.6) / (pow(x, 1.5632) * 0.1674199 + 1.0730397)) * 1.2404596);\n"
   "	if (m == 6)         /* Drago */\n"
   "		return dt_shoulder(v, log(1.0 + x) / log(2.0 + 8.0 * pow(x / 8.0, 0.2344653))\n"
   "		                      * (1.0 / 0.9542425) * 2.6616800);\n"
   "	if (m == 7)         /* Unreal */\n"
   "		return dt_shoulder(v, pow(v / (v + 0.155) * 1.019, 2.2) * 1.3173380);\n"
   "	if (m == 8)         /* Filmic ALU (Hejl 2015) */\n"
   "	{\n"
   "		highp float va = 1.425 * x + 0.05;\n"
   "		highp float f  = ((x * va + 0.004) / ((x * va + 0.055) + 0.0491)) - 0.0821;\n"
   "		return dt_shoulder(v, pow(max(f, 0.0), 2.2) * 1.4132626);\n"
   "	}\n"
   "	if (m == 9)         /* Reinhard (plain) */\n"
   "		return dt_shoulder(v, (x / (1.0 + x)) * 2.0);\n"
   "	if (m == 10)        /* Reinhard (extended, white 4) */\n"
   "		return dt_shoulder(v, (x * (1.0 + x / 16.0) / (1.0 + x)) * 1.8823529);\n"
   "	if (m == 11)        /* Exponential */\n"
   "		return dt_shoulder(v, (1.0 - exp(-x)) * 1.5819767);\n"
   "	if (m == 12)        /* Hable 2017 piecewise */\n"
   "	{\n"
   "		highp float f;\n"
   "		if (x < 0.25)\n"
   "			f = 1.1313708 * pow(x, 1.25);\n"
   "		else if (x < 0.70)\n"
   "			f = 0.20 + (x - 0.25);\n"
   "		else\n"
   "			f = 0.65 + 0.35 * (x - 0.70) / ((x - 0.70) + 0.35);\n"
   "		return dt_shoulder(v, f * 1.2322275);\n"
   "	}\n"
   "	if (m == 13)        /* ACES 2.0 tone scale alone */\n"
   "	{\n"
   "		highp float f = 1.0471038 * pow(x / (x + 0.9198583), 1.15);\n"
   "		return dt_shoulder(v, (f * f / (f + 0.04)) * 2.1854781);\n"
   "	}\n"
   "	if (m == 14)        /* Tumblin-Rushmeier */\n"
   "		return dt_shoulder(v, pow(x, 0.6075));\n"
   "	if (m == 15)        /* Ward */\n"
   "		return dt_shoulder(v, x);\n"
   "	if (m == 16)        /* Schlick */\n"
   "		return dt_shoulder(v, 2.3 * x / (2.3 * x - x + 1.0));\n"
   "	/* 17: Reinhard-Devlin */\n"
   "	return dt_shoulder(v, (x / (x + 0.3010864)) * 1.3010864);\n"
   "}\n"
   "\n"
   "/* HDR Expansion: lifts the top of the range into the headroom. */\n"
   "highp vec3 dt_expand_curve(highp vec3 v, highp float E, highp float K)\n"
   "{\n"
   "	highp vec3 t  = clamp((v - K) / max(1.0 - K, 1e-4), 0.0, 1.0);\n"
   "	highp vec3 hi = K + (1.0 - K) * t + (E - 1.0) * t * t + max(v - 1.0, 0.0);\n"
   "	return mix(v, hi, step(vec3(K), v));\n"
   "}\n"
   "\n"
   "highp vec3 dt_expand(highp vec3 c)\n"
   "{\n"
   "	highp float E = dt.mode.y, p;\n"
   "	if (dt.mode.w < 0.5 || E <= 1.0001)\n"
   "		return c;\n"
   "	if (dt.mode.w < 1.5)\n"
   "		return dt_expand_curve(c, E, dt.film.z);\n"
   "	p = max(c.r, max(c.g, c.b));\n"
   "	if (p <= 1e-5)\n"
   "		return c;\n"
   "	return c * (dt_expand_curve(vec3(p), E, dt.film.z).x / p);\n"
   "}\n"
   "\n"
   "/* Scene Rec.709 (1.0 = paper white) -> Rec.709 in paper-white units, or,\n"
   " * for ACES 2.0 (full), Rec.2020 nits; `absolute` tells the caller which. */\n"
   "highp vec3 dt_apply(highp vec3 v, highp float paper_white_nits, out bool absolute)\n"
   "{\n"
   "	highp float pre;\n"
   "	int m = int(dt.mode.x + 0.5);\n"
   "	v = dt_expand(max(v, vec3(0.0)));\n"
   "	absolute = (m == 23);\n"
   "	if (absolute)\n"
   "		return dt.aces2ToOut * dt_aces2(v) * 100.0;\n"
   "	pre = max(v.r, max(v.g, v.b));\n"
   "	if (m >= 18)\n"
   "		v = dt_curve_rgb(v);\n"
   "	else\n"
   "		v = vec3(dt_curve(v.r), dt_curve(v.g), dt_curve(v.b));\n"
   "	if (dt.mode.z > 0.5)   /* Highlight Hue Preservation */\n"
   "	{\n"
   "		highp float post = max(v.r, max(v.g, v.b));\n"
   "		highp float g    = 1.0 - 1.0 / (0.15 * max(pre - post, 0.0) + 1.0);\n"
   "		v = mix(v, vec3(post), g);\n"
   "	}\n"
   "	return v;\n"
   "}\n"
   "\n"
   "#endif /* HDR_TRANSFORM_H */\n"
   "/* ---- end hdr_transform.h ---- */\n"
   "#endif\n"
   "\n"
   "/* The grade both HDR outputs share: linear light in, absolute nits out, in\n"
   " * the Rec.2020 container after the Colour Boost rotation and panel gamut\n"
   " * compression. `scene_linear` is normalised with 1.0 at reference white;\n"
   " * values above that are the additive overshoot the roll-off compresses. */\n"
   "highp vec3 hdr_grade_linear(highp vec3 scene_linear, highp float paper_white_nits,\n"
   "                            highp float peak_nits, int expand_gamut, int shoulder,\n"
   "                            int src_primaries, highp mat3 to_panel)\n"
   "{\n"
   "	/* STEP 3: one transfer function across the whole range, then compress\n"
   "	 * whatever lands above paper white.\n"
   "	 *\n"
   "	 * The signal is PSX-native and gamma-encoded; sdr_to_linear is the\n"
   "	 * display transfer (defaulting to the pure 2.4 RetroArch uses in its own\n"
   "	 * Vulkan/D3D HDR shaders). Applying it to the whole value - including the >1.0 left in the 16F\n"
   "	 * framebuffer by additive blends - is what keeps the encode continuous.\n"
   "	 * Decoding only [0,1] and treating the overshoot as if it were already\n"
   "	 * linear light mixes two domains in one sum, and the slope then steps by\n"
   "	 * headroom/(2.4*paper_white) - 1.67x at 200/1000 nits - exactly at\n"
   "	 * reference white, which contours any gradient that crosses it and makes\n"
   "	 * the deband grain visibly coarsen at the same threshold.\n"
   "	 *\n"
   "	 * Content in [0,1] is untouched by this: the transfer maps 1.0 to 1.0 for\n"
   "	 * every sdr_eotf, so sdr_to_linear(c)*paper_white <= paper white, so the roll-off below never engages and the standard range still\n"
   "	 * maps bit-for-bit onto the SDR result.\n"
   "	 *\n"
   "	 * The knee is driven by the peak (brightest) overshoot channel and the\n"
   "	 * overshoot is scaled proportionally, rather than kneeing each channel on\n"
   "	 * its own: a per-channel roll-off compresses the brightest channel hardest,\n"
   "	 * which desaturates a hot coloured highlight toward white (a saturated\n"
   "	 * additive red would wash out as it brightens). Scaling by the shared\n"
   "	 * factor keeps the overshoot's chromaticity, so a hot additive red stays\n"
   "	 * red. Dim channels are left alone, as before. */\n"
   "	/* peak_nits is what the display can actually reach, supplied by the\n"
   "	 * frontend as GET_HDR_METADATA max_nits. Everything above paper white and\n"
   "	 * below it is the headroom available for highlights, so a wrong value is\n"
   "	 * either wasted range or clipping - which is why this stopped being the\n"
   "	 * hardcoded 1000 it was.\n"
   "	 *\n"
   "	 * The frontend may report a peak below paper white if the user has set it\n"
   "	 * that way; headroom then clamps to zero and the roll-off degenerates to a\n"
   "	 * clamp at paper white, which is the right behaviour rather than a\n"
   "	 * negative range. */\n"
   "#ifdef HDR_DT\n"
   "	/* The Display Transform option replaces the knee below. */\n"
   "	if (dt.mode.x > 0.5)\n"
   "	{\n"
   "		bool absolute;\n"
   "		highp vec3 v = dt_apply(src_primaries_to_709(max(scene_linear, vec3(0.0)), src_primaries),\n"
   "		                        paper_white_nits, absolute);\n"
   "		if (absolute)\n"
   "			return v;\n"
   "		return panel_gamut_compress(rec709_to_target(v * paper_white_nits, expand_gamut), to_panel);\n"
   "	}\n"
   "#endif\n"
   "	highp float headroom = max(peak_nits - paper_white_nits, 0.0);\n"
   "	highp vec3  lin      = src_primaries_to_709(max(scene_linear, vec3(0.0)), src_primaries)\n"
   "	                     * paper_white_nits;\n"
   "	/* Linear-light overshoot. Forced to zero when there is no headroom\n"
   "	 * (paper white at or above the ceiling), which clamps to paper white\n"
   "	 * instead of letting the knee pass the value through unscaled. */\n"
   "	highp vec3  over     = (headroom > 0.0)\n"
   "	                          ? max(lin - vec3(paper_white_nits), vec3(0.0))\n"
   "	                          : vec3(0.0);\n"
   "	highp float omax     = max(over.r, max(over.g, over.b));\n"
   "	highp float o        = (omax > 0.0) ? (omax / headroom) : 0.0;\n"
   "	/* Per-unit-overshoot factor S(o)/o, shared across channels. shoulder\n"
   "	 * selects S: 0 = Reinhard o/(o+1) (S/o = 1/(o+1)); 1 = filmic. Both have\n"
   "	 * S'(0) == 1, so the peak channel leaves white at the same slope it\n"
   "	 * arrived with and asymptotes to the ceiling.\n"
   "	 *\n"
   "	 * (1-exp(-o))/o cancels catastrophically as o -> 0 - fp32 loses 40% of the\n"
   "	 * value by o = 1e-7, and that is precisely the neighbourhood of reference\n"
   "	 * white - so the small-o branch uses the series 1 - o/2 + o^2/6, which is\n"
   "	 * good to ~1e-7 at the crossover and exact at the origin. */\n"
   "	highp float knee     = 0.0;\n"
   "	if (o > 0.0)\n"
   "	{\n"
   "		if (shoulder == 1)\n"
   "			knee = (o < 1e-2)\n"
   "			          ? (1.0 - o * (0.5 - o * (1.0 / 6.0)))\n"
   "			          : (filmic_shoulder(o) / o);\n"
   "		else\n"
   "			knee = 1.0 / (o + 1.0);\n"
   "	}\n"
   "	lin = min(lin, vec3(paper_white_nits)) + over * knee;\n"
   "	lin = rec709_to_target(lin, expand_gamut);\n"
   "	return panel_gamut_compress(lin, to_panel);\n"
   "}\n"
   "\n"
   "/* Rec.2020 -> Rec.709, the inverse of the Accurate rotation. */\n"
   "highp vec3 rec2020_to_709(highp vec3 c)\n"
   "{\n"
   "	return vec3(\n"
   "		 1.6604903 * c.r + -0.5876391 * c.g + -0.0728516 * c.b,\n"
   "		-0.1245500 * c.r +  1.1328999 * c.g + -0.0083480 * c.b,\n"
   "		-0.0181511 * c.r + -0.1005787 * c.g +  1.1187299 * c.b);\n"
   "}\n"
   "\n"
   "/* HDR output from linear light, in the format the frontend accepted.\n"
   " *\n"
   " *   scrgb == 0  HDR10: PQ-encoded Rec.2020, with the black-floor toe in the\n"
   " *               PQ domain.\n"
   " *   scrgb != 0  RETRO_PIXEL_FORMAT_SCRGB_RGBA16F: linear Rec.709, 1.0 = 80\n"
   " *               nits. The same graded light, so the two formats present the\n"
   " *               same picture: the container rotation is undone exactly, colours\n"
   " *               outside Rec.709 are negative rather than clipped, and the toe\n"
   " *               is applied through a PQ round trip so it lands where the HDR10\n"
   " *               path puts it. That round trip runs only when a black level is\n"
   " *               known.\n"
   " *\n"
   " * scrgb comes from a push constant, so the branch is uniform. */\n"
   "highp vec3 encode_hdr_output_linear(highp vec3 scene_linear, highp float paper_white_nits,\n"
   "                                    highp float peak_nits, int expand_gamut, int shoulder,\n"
   "                                    int src_primaries, highp float black_pq,\n"
   "                                    highp mat3 to_panel, int scrgb)\n"
   "{\n"
   "	highp vec3 lin = hdr_grade_linear(scene_linear, paper_white_nits, peak_nits,\n"
   "	                                  expand_gamut, shoulder, src_primaries, to_panel);\n"
   "	if (scrgb == 0)\n"
   "		return pq_black_floor(pq_encode(lin), black_pq);\n"
   "	if (black_pq > 0.0)\n"
   "		lin = pq_decode(pq_black_floor(pq_encode(lin), black_pq));\n"
   "	return rec2020_to_709(lin) * (1.0 / 80.0);\n"
   "}\n"
   "\n"
   "highp vec3 encode_hdr_output(highp vec3 rgb, highp float paper_white_nits, highp float peak_nits,\n"
   "                             int expand_gamut, int shoulder, int sdr_eotf, int src_primaries,\n"
   "                             highp float black_pq, highp mat3 to_panel, int scrgb)\n"
   "{\n"
   "	return encode_hdr_output_linear(sdr_to_linear(max(rgb, vec3(0.0)), sdr_eotf),\n"
   "	                                paper_white_nits, peak_nits, expand_gamut, shoulder,\n"
   "	                                src_primaries, black_pq, to_panel, scrgb);\n"
   "}\n"
   "\n"
   "/* HDR post effects (bloom, halation, chromatic aberration). With\n"
   " * HDR_LINEAR_OUT set the display stage writes scene-linear light - 1.0 at\n"
   " * reference white, still in the authoring primaries - to a half-float image\n"
   " * instead of encoding, and hdr_post.frag encodes after the effects. A\n"
   " * specialization constant on Vulkan, so the default pipelines compile to the\n"
   " * code they always had; a uniform on GL. Constant 1 is the primitive\n"
   " * shaders' FILTER_TYPE slot, which no display program shares. */\n"
   "#if defined(HDR)\n"
   "#ifdef VULKAN\n"
   "layout(constant_id = 1) const int HDR_LINEAR_OUT = 0;\n"
   "#else\n"
   "uniform int HDR_LINEAR_OUT;\n"
   "#endif\n"
   "#endif\n"
   "\n"
   "/* ---- Debanding dither -----------------------------------------------------\n"
   " * For the genuinely-8-bit paths whose gradients are already quantised and\n"
   " * would band at 10-bit. ~1 8-bit-LSB of triangular-PDF noise, spatially\n"
   " * distributed with interleaved gradient noise (blue-noise-like, no texture),\n"
   " * applied in gamma space. TPDF decorrelates the noise from the signal, so it\n"
   " * reads as a faint even grain. Not for interpolated content (mipmap resolve,\n"
   " * YUV chroma) - that already carries sub-8-bit precision 10-bit preserves. */\n"
   "highp float hdr_ign(highp vec2 p, highp vec2 k)  /* IGN along direction k -> [0,1) */\n"
   "{\n"
   "	return fract(52.9829189 * fract(dot(p, k)));\n"
   "}\n"
   "\n"
   "highp float hdr_tri(highp float u)  /* uniform [0,1) -> triangular (-1,1) */\n"
   "{\n"
   "	return u < 0.5 ? sqrt(2.0 * u) - 1.0 : 1.0 - sqrt(2.0 - 2.0 * u);\n"
   "}\n"
   "\n"
   "highp vec3 hdr_deband(highp vec3 rgb, highp vec2 fragcoord)\n"
   "{\n"
   "	/* Per-channel IGN *direction* (not a shared field offset) gives three\n"
   "	 * decorrelated fields, so the grain carries no chroma tint (pairwise\n"
   "	 * channel correlation ~0). Each is remapped to a triangular PDF. */\n"
   "	highp vec3 t = vec3(\n"
   "		hdr_tri(hdr_ign(fragcoord, vec2( 0.06711056,  0.00583715))),\n"
   "		hdr_tri(hdr_ign(fragcoord, vec2( 0.00583715,  0.06711056))),\n"
   "		hdr_tri(hdr_ign(fragcoord, vec2( 0.06711056, -0.00583715))));\n"
   "	return rgb + t * (1.0 / 255.0);\n"
   "}\n"
   "\n"
   "/* Luma-only variant for the YUV FMV path. Its chroma is reconstructed at\n"
   " * sub-8-bit precision (2x2 average + bilinear) that 10-bit preserves, so it\n"
   " * must NOT be dithered; only the per-pixel 8-bit luma steps. An equal offset\n"
   " * to R,G,B is chroma-neutral through the BT.601 matrix (U,V rows sum ~0, Y\n"
   " * row 1), so one triangular sample on all channels dithers luma alone. */\n"
   "highp vec3 hdr_deband_luma(highp vec3 rgb, highp vec2 fragcoord)\n"
   "{\n"
   "	highp float t = hdr_tri(hdr_ign(fragcoord, vec2(0.06711056, 0.00583715)));\n"
   "	return rgb + vec3(t) * (1.0 / 255.0);\n"
   "}\n"
   "\n"
   "#endif /* HDR_H */\n"
   "/* ---- end hdr.h ---- */\n"
   "\n"
   "in highp vec2 vUV;\n"
   "out highp vec4 FragColor;\n"
   "\n"
   "uniform sampler2D uDecoded;\n"
   "\n"
   "uniform vec2 reg_sig_size;\n"
   "uniform vec2 reg_out_size;\n"
   "uniform int reg_sdr_eotf;\n"
   "uniform float reg_paper_white_nits;\n"
   "uniform float reg_peak_nits;\n"
   "uniform int reg_expand_gamut;\n"
   "uniform int reg_shoulder;\n"
   "uniform int reg_src_primaries;\n"
   "uniform float reg_black_pq;\n"
   "uniform int reg_scrgb;\n"
   "uniform mat3 reg_to_panel;\n"
   "\n"
   "void main()\n"
   "{\n"
   "	highp float row = vUV.y;\n"
   "\n"
   "	/* Base samples per output pixel. At 1x this is `div` and the box is the\n"
   "	 * exact inverse of the CRTC hold. Above 1x the window narrows and the\n"
   "	 * sub-native structure the cable produces - ringing, chroma smear, dot\n"
   "	 * crawl, all at base-clock rate - survives instead of averaging flat.\n"
   "	 * Below 1 the band-limited signal is simply interpolated. */\n"
   "	highp float bpo = reg_sig_size.x / max(reg_out_size.x, 1.0);\n"
   "	highp float n0  = floor(gl_FragCoord.x) * bpo;\n"
   "	highp int   num = int(clamp(floor(bpo + 0.5), 1.0, 16.0));\n"
   "\n"
   "	highp vec3  acc = vec3(0.0);\n"
   "	highp float cnt = 0.0;\n"
   "	int i;\n"
   "	for (i = 0; i < 16; i++)\n"
   "	{\n"
   "		if (i >= num)\n"
   "			break;\n"
   "		highp float k = clamp(n0 + float(i), 0.0, reg_sig_size.x - 1.0);\n"
   "		highp vec3  v = textureLod(uDecoded, vec2((k + 0.5) / reg_sig_size.x, row), 0.0).rgb;\n"
   "		acc += sdr_to_linear(clamp(v, vec3(0.0), vec3(1.0)), reg_sdr_eotf);\n"
   "		cnt += 1.0;\n"
   "	}\n"
   "\n"
   "	highp vec3 lin = acc / max(cnt, 1.0);\n"
   "\n"
   "#if defined(HDR)\n"
   "	/* encode_hdr_output_linear rotates the primaries itself. */\n"
   "	if (HDR_LINEAR_OUT != 0)\n"
   "	{\n"
   "		FragColor = vec4(lin, 1.0);\n"
   "	}\n"
   "	else\n"
   "	{\n"
   "		FragColor = vec4(encode_hdr_output_linear(lin, reg_paper_white_nits, reg_peak_nits,\n"
   "		                                          reg_expand_gamut, reg_shoulder,\n"
   "		                                          reg_src_primaries, reg_black_pq,\n"
   "		                                          reg_to_panel, reg_scrgb), 1.0);\n"
   "	}\n"
   "#else\n"
   "	/* Rotated here rather than through sdr_apply_src_primaries: this pass is\n"
   "	 * already holding linear light, so it costs a matrix and no round trip. */\n"
   "	FragColor = vec4(linear_to_sdr(src_primaries_to_709(lin, reg_src_primaries),\n"
   "	                               reg_sdr_eotf), 1.0);\n"
   "#endif\n"
   "}\n"
   ;

static const char *analog_resolve_glsl_ES =
   "#version 300 es\n"
   "precision highp float;\n"
   "precision highp int;\n"
   "\n"
   "precision highp float;\n"
   "precision highp int;\n"
   "\n"
   "/* Pass 4: resample base clock -> display, and hand off to the display encode.\n"
   " *\n"
   " * Everything upstream now emits RGB at base rate, so this is a box filter and\n"
   " * nothing else. It used to carry the chroma demodulator, which meant running a\n"
   " * 31-tap filter once per base sample *per output pixel* - the same work\n"
   " * repeated at every internal-resolution multiple. Demodulating once at base\n"
   " * rate and resampling afterwards makes this pass essentially free and makes the\n"
   " * chain's cost independent of internal resolution.\n"
   " *\n"
   " * Output is gamma-domain R'G'B', exactly what the display quad would otherwise\n"
   " * have produced, so the HDR10 encode here is the one the normal path uses.\n"
   " *\n"
   " * The box averages *light*, not signal. The samples being combined are what a\n"
   " * phosphor would have integrated over the span of one output pixel, and a\n"
   " * phosphor integrates emitted light - so the transfer function belongs inside\n"
   " * the average, not after it. Averaging the voltage and applying gamma once is\n"
   " * darker by Jensen's inequality: about 6% on a +-10% ripple and up to 62% at a\n"
   " * hard black-to-white edge, which is precisely where output pixels straddle a\n"
   " * transition.\n"
   " *\n"
   " * Clamped to [0,1] first. Band-limiting rings and the comb leaks, so the\n"
   " * decoded signal does overshoot at sharp edges - but that is filter ringing,\n"
   " * not light. A television clips it, and treating it as emissive content makes\n"
   " * every edge glow. */\n"
   "\n"
   "/* ---- begin hdr.h ---- */\n"
   "/* ---- Shared HDR10 (PQ Rec.2020) output math -------------------------------\n"
   " * Included by the Vulkan display shaders (quad.frag, mipmap_resolve.frag)\n"
   " * under -DHDR. Every entry point is parameterised - paper white and the gamut\n"
   " * mode are passed in - so each shader supplies them from its own push\n"
   " * constant rather than this header reaching into a fixed `registers` layout.\n"
   " *\n"
   " * The colour math matches the prboom \"Color Format = HDR\" path and\n"
   " * RetroArch's own HDR composition, so an HDR frame lands at the same\n"
   " * brightness and saturation as the SDR one:\n"
   " *   - display transfer is a pure pow(2.4) (RetroArch linearises SDR with 2.4\n"
   " *     in its Vulkan/D3D HDR shaders; the sRGB piecewise curve is wrong here\n"
   " *     and lifts blacks),\n"
   " *   - ordinary content is scaled to paper white,\n"
   " *   - Rec.709 -> target primaries keyed to the frontend \"Colour Boost\" (same\n"
   " *     matrices RetroArch applies, so switching SDR<->HDR10 does not shift\n"
   " *     saturation),\n"
   " *   - colours the panel cannot show compressed toward its own gamut boundary,\n"
   " *     when the frontend reports the panel's primaries,\n"
   " *   - SMPTE ST.2084 (PQ) encode over 0..10000 nits, with the bottom of the\n"
   " *     range lifted onto the panel's black when the frontend reports one.\n"
   " * Runs in highp; precision qualifiers are ignored on the desktop Vulkan\n"
   " * target but keep the intent explicit. */\n"
   "#ifndef HDR_H\n"
   "#define HDR_H\n"
   "\n"
   "/* The HDR output variants carry the Display Transform (hdr_transform.h). */\n"
   "#if defined(HDR) && !defined(HDR_DT)\n"
   "#define HDR_DT\n"
   "#endif\n"
   "\n"
   "const highp float PQ_M1     = 2610.0 / 16384.0;\n"
   "const highp float PQ_M2     = (2523.0 / 4096.0) * 128.0;\n"
   "const highp float PQ_C1     = 3424.0 / 4096.0;\n"
   "const highp float PQ_C2     = (2413.0 / 4096.0) * 32.0;\n"
   "const highp float PQ_C3     = (2392.0 / 4096.0) * 32.0;\n"
   "const highp float PQ_MAXNITS = 10000.0;\n"
   "\n"
   "highp vec3 pq_encode(highp vec3 nits)\n"
   "{\n"
   "	highp vec3 y  = clamp(nits / PQ_MAXNITS, vec3(0.0), vec3(1.0));\n"
   "	highp vec3 ym = pow(y, vec3(PQ_M1));\n"
   "	return pow((PQ_C1 + PQ_C2 * ym) / (1.0 + PQ_C3 * ym), vec3(PQ_M2));\n"
   "}\n"
   "\n"
   "highp vec3 pq_decode(highp vec3 e)\n"
   "{\n"
   "	highp vec3 p = pow(clamp(e, vec3(0.0), vec3(1.0)), vec3(1.0 / PQ_M2));\n"
   "	return PQ_MAXNITS * pow(max(p - vec3(PQ_C1), vec3(0.0)) / (vec3(PQ_C2) - PQ_C3 * p),\n"
   "	                        vec3(1.0 / PQ_M1));\n"
   "}\n"
   "\n"
   "/* Inverse of sdr_to_linear. Needed wherever something has to be averaged as\n"
   " * light and then handed back to a signal-domain consumer. */\n"
   "highp vec3 linear_to_sdr(highp vec3 c, int sdr_eotf)\n"
   "{\n"
   "	c = max(c, vec3(0.0));\n"
   "	if (sdr_eotf == 1)\n"
   "		return pow(c, vec3(1.0 / 2.2));\n"
   "	if (sdr_eotf == 2)\n"
   "		return mix(1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055,\n"
   "		           c * 12.92,\n"
   "		           lessThanEqual(c, vec3(0.0031308)));\n"
   "	return pow(c, vec3(1.0 / 2.4));\n"
   "}\n"
   "\n"
   "/* Source primaries, applied to linear light before the target rotation below.\n"
   " *\n"
   " * The framebuffer is R'G'B', but which chromaticities those coordinates *mean*\n"
   " * is a property of the display the content was authored on, and PSX-era content\n"
   " * was not authored on Rec.709. This is orthogonal to the cable: primaries are a\n"
   " * property of the authoring monitor, not the wire, so RGB output wants the same\n"
   " * treatment as composite.\n"
   " *\n"
   " *   1  SMPTE-C  (BT.601 525) - what NTSC-era studio monitors used\n"
   " *   2  EBU      (BT.601 625) - PAL. Differs from Rec.709 in green alone and by\n"
   " *                              only 4%, which is why PAL barely moves.\n"
   " *   3  NTSC 1953             - the original, aspirational FCC primaries.\n"
   " *                              Enormously wider: its green lands at -0.40 in\n"
   " *                              Rec.709, i.e. 40% outside the gamut, so it is\n"
   " *                              only actually representable in a wide container.\n"
   " *                              Reportedly retained in Japan, though the better\n"
   " *                              documented NTSC-J difference is black setup, so\n"
   " *                              treat this as flavour rather than accuracy.\n"
   " *\n"
   " * Every one of these maps some primary outside Rec.709, so on an SDR output the\n"
   " * result clips; under HDR10 the Rec.2020 container holds it. Default is 0, no\n"
   " * rotation, which leaves the 24-bit path and the HDR path agreeing. */\n"
   "highp vec3 src_primaries_to_709(highp vec3 c, int src_primaries)\n"
   "{\n"
   "	if (src_primaries == 1)          /* SMPTE-C */\n"
   "		return vec3(\n"
   "			 0.939542064 * c.r +  0.050181357 * c.g +  0.010276579 * c.b,\n"
   "			 0.017772223 * c.r +  0.965792862 * c.g +  0.016434914 * c.b,\n"
   "			-0.001621600 * c.r + -0.004369750 * c.g +  1.005991350 * c.b);\n"
   "	else if (src_primaries == 2)     /* EBU */\n"
   "		return vec3(\n"
   "			 1.044043209 * c.r + -0.044043209 * c.g,\n"
   "			                       c.g,\n"
   "			                       0.011793378 * c.g +  0.988206622 * c.b);\n"
   "	else if (src_primaries == 3)     /* NTSC 1953, Bradford-adapted C -> D65 */\n"
   "		return vec3(\n"
   "			 1.486156846 * c.r + -0.403554906 * c.g + -0.082601940 * c.b,\n"
   "			-0.025101109 * c.r +  0.954024686 * c.g +  0.071076423 * c.b,\n"
   "			-0.027224002 * c.r + -0.044095233 * c.g +  1.071319235 * c.b);\n"
   "	return c;\n"
   "}\n"
   "\n"
   "/* Gamut rotation, applied to linear light. Cases mirror prboom / RetroArch:\n"
   " * 0 Accurate (709->2020), 1 Expanded, 2 Wide (709->P3), 3 Super (no rotation). */\n"
   "highp vec3 rec709_to_target(highp vec3 c, int expand_gamut)\n"
   "{\n"
   "	if (expand_gamut == 1)          /* Expanded */\n"
   "		return vec3(\n"
   "			 0.6274040 * c.r +  0.3292820 * c.g +  0.0433136 * c.b,\n"
   "			 0.0457456 * c.r +  0.9417770 * c.g +  0.0124772 * c.b,\n"
   "			-0.0012106 * c.r +  0.0176041 * c.g +  0.9836070 * c.b);\n"
   "	else if (expand_gamut == 2)     /* Wide (DCI-P3) */\n"
   "		return vec3(\n"
   "			 0.8215873 * c.r +  0.1763479 * c.g +  0.0020641 * c.b,\n"
   "			 0.0328261 * c.r +  0.9695096 * c.g + -0.0023367 * c.b,\n"
   "			 0.0188038 * c.r +  0.0725063 * c.g +  0.9086907 * c.b);\n"
   "	else if (expand_gamut == 3)     /* Super (stay Rec.709) */\n"
   "		return c;\n"
   "	/* Accurate: proper Rec.709 -> Rec.2020 */\n"
   "	return vec3(\n"
   "		0.6274040 * c.r + 0.3292820 * c.g + 0.0433136 * c.b,\n"
   "		0.0690970 * c.r + 0.9195400 * c.g + 0.0113612 * c.b,\n"
   "		0.0163916 * c.r + 0.0880132 * c.g + 0.8955950 * c.b);\n"
   "}\n"
   "\n"
   "/* Reference SDR transfer, applied to the whole signal (see encode_hdr_output).\n"
   " *   0  BT.1886 pure 2.4 - matches RetroArch's own SDR->HDR composition and a\n"
   " *      TV-like reference display. Historical behaviour, still the default.\n"
   " *   1  pure 2.2 - closer to a PC monitor tracking sRGB's nominal gamma.\n"
   " *   2  sRGB piecewise - what Windows assumes when it composites SDR content\n"
   " *      into an HDR desktop. Lifts the toe relative to 2.4.\n"
   " * This is a viewing-reference choice, not a correctness one: it decides\n"
   " * whether 30-bit HDR lands at the same brightness the 24-bit path did on the\n"
   " * same display. Against a 2.2 monitor, 2.4 is 12.9% down in linear light at\n"
   " * code 0.5 and 24.2% down at 0.25, which reads as \"HDR looks dimmer and more\n"
   " * contrasty\". All three agree exactly at 0.0 and 1.0, so paper white and the\n"
   " * roll-off knee threshold do not move, and all extend monotonically past 1.0\n"
   " * so the additive overshoot decodes with the same curve as everything else. */\n"
   "highp vec3 sdr_to_linear(highp vec3 c, int sdr_eotf)\n"
   "{\n"
   "	if (sdr_eotf == 1)\n"
   "		return pow(c, vec3(2.2));\n"
   "	if (sdr_eotf == 2)\n"
   "		return mix(pow((c + vec3(0.055)) / 1.055, vec3(2.4)),\n"
   "		           c / 12.92,\n"
   "		           lessThanEqual(c, vec3(0.04045)));\n"
   "	return pow(c, vec3(2.4));\n"
   "}\n"
   "\n"
   "highp float filmic_shoulder(highp float x)\n"
   "{\n"
   "	/* Punchier alternative to Reinhard's o/(o+1) as the highlight-shoulder\n"
   "	 * magnitude: maps the normalised overshoot [0,inf) to [0,1), rising faster\n"
   "	 * and reaching the ceiling sooner (0.63 vs 0.50 at x=1, 0.86 vs 0.67 at\n"
   "	 * x=2), which is the behaviour the \"filmic\" roll-off option documents.\n"
   "	 *\n"
   "	 * Both shoulders have to satisfy S'(0) == 1: that is what keeps the encode\n"
   "	 * C1-continuous where the overshoot region joins reference white, because\n"
   "	 * the slope just above white is S'(0) * d(lin)/dc against d(lin)/dc just\n"
   "	 * below it. The Narkowicz ACES fit previously used here has S'(0) = b/e =\n"
   "	 * 0.214 and so dropped the slope 4.7x exactly at white. Normalising it\n"
   "	 * (scaling the input by e/b) restores the origin slope but sends the peak\n"
   "	 * derivative to ~8.4, trading the step for a worse spike a few percent\n"
   "	 * above white. 1 - exp(-x) has unit slope at the origin and a maximum\n"
   "	 * derivative of 1, so it is smooth on both counts, and is cheaper than the\n"
   "	 * rational fit it replaces. */\n"
   "	return 1.0 - exp(-x);\n"
   "}\n"
   "\n"
   "/* Source primaries for a signal-domain consumer: decode, rotate, re-encode.\n"
   " *\n"
   " * The HDR path gets this for free inside encode_hdr_output, which is already\n"
   " * holding linear light. An SDR output has to round-trip for it, which is two\n"
   " * extra pow() per pixel - so the identity case returns immediately, and a\n"
   " * default configuration pays nothing.\n"
   " *\n"
   " * Every one of the rotations maps some primary outside Rec.709, and an SDR\n"
   " * output clips those. That is a real loss and the reason NTSC 1953 in\n"
   " * particular only makes sense on a wide-gamut display - but clipping the\n"
   " * out-of-gamut corners is still closer to the intended picture than\n"
   " * interpreting SMPTE-C coordinates as Rec.709 ones, which is what happens\n"
   " * otherwise. */\n"
   "highp vec3 sdr_apply_src_primaries(highp vec3 rgb, int sdr_eotf, int src_primaries)\n"
   "{\n"
   "	if (src_primaries == 0)\n"
   "		return rgb;\n"
   "	return linear_to_sdr(\n"
   "		src_primaries_to_709(sdr_to_linear(max(rgb, vec3(0.0)), sdr_eotf), src_primaries),\n"
   "		sdr_eotf);\n"
   "}\n"
   "\n"
   "/* Panel gamut compression, applied to linear Rec.2020 nits.\n"
   " *\n"
   " * The Rec.2020 container holds colours no consumer panel can show - the\n"
   " * NTSC 1953 primaries, the Colour Boost modes and saturated additive\n"
   " * highlights all land there - and a panel left to its own devices clips them\n"
   " * per channel, which flattens gradients and shifts hue. to_panel maps\n"
   " * Rec.2020 into the panel's own RGB, where \"outside the gamut\" is simply a\n"
   " * channel below zero.\n"
   " *\n"
   " * In panel RGB each channel's distance from the achromatic axis is\n"
   " * d = (max - c) / max: 0 on the axis, 1 on the gamut boundary, above 1\n"
   " * outside it. Distances past the threshold are compressed with\n"
   " * t + x / (1 + x / (1 - t)), which has unit slope where it starts and\n"
   " * approaches the boundary asymptotically, so nothing is clipped and the\n"
   " * transition is C1. The largest channel is untouched, so the highlight\n"
   " * roll-off's luminance placement survives. Only the outer tenth of the\n"
   " * panel's own gamut is touched among colours it can show; everything\n"
   " * further in, which is nearly all content, passes through bit for bit.\n"
   " *\n"
   " * A zero matrix means the panel is unknown, and the colour is returned as is. */\n"
   "highp vec3 panel_gamut_compress(highp vec3 lin2020, highp mat3 to_panel)\n"
   "{\n"
   "	const highp float T = 0.9;\n"
   "	const highp float S = 1.0 - T;\n"
   "	highp vec3  p;\n"
   "	highp float ach;\n"
   "	highp vec3  d;\n"
   "	highp vec3  x;\n"
   "	if (to_panel[0][0] == 0.0)\n"
   "		return lin2020;\n"
   "	p   = to_panel * lin2020;\n"
   "	ach = max(p.r, max(p.g, p.b));\n"
   "	if (ach <= 0.0)\n"
   "		return lin2020;\n"
   "	d   = (vec3(ach) - p) / ach;\n"
   "	if (max(d.r, max(d.g, d.b)) <= T)\n"
   "		return lin2020;\n"
   "	x   = max(d - vec3(T), vec3(0.0));\n"
   "	d   = mix(d, vec3(T) + x / (vec3(1.0) + x / S), greaterThan(d, vec3(T)));\n"
   "	return inverse(to_panel) * (vec3(ach) - d * ach);\n"
   "}\n"
   "\n"
   "/* Display black floor: the BT.2390 EETF toe, E + b * (1 - E)^4 in the PQ\n"
   " * domain, with b = PQ(panel black). A panel cannot go below its black, so\n"
   " * without this everything encoded under it is crushed into one level; the\n"
   " * toe lands code 0 on the panel's black and lifts the shadows above it with\n"
   " * a weight that has fallen to nothing well before paper white. b is computed\n"
   " * on the CPU; at 0 the curve is the identity. */\n"
   "highp vec3 pq_black_floor(highp vec3 e, highp float black_pq)\n"
   "{\n"
   "	highp vec3 t;\n"
   "	if (black_pq <= 0.0)\n"
   "		return e;\n"
   "	t = vec3(1.0) - e;\n"
   "	t = t * t;\n"
   "	return e + black_pq * (t * t);\n"
   "}\n"
   "\n"
   "#ifdef HDR_DT\n"
   "/* ---- begin hdr_transform.h ---- */\n"
   "/* ---- Display transform (tone curves, ACES 2.0, expansion) ---------------\n"
   " * The \"Display Transform\" core option, applied by hdr_grade_linear when\n"
   " * dt.mode.x is non-zero; 0 keeps the soft knee in hdr.h. Shared with the\n"
   " * GL backend through gen_analog_gl.py. The constants come from\n"
   " * rhi/hdr_transform.c, which also holds CPU twins of every curve.\n"
   " *\n"
   " * Input is scene-linear Rec.709 with 1.0 at paper white. Every curve\n"
   " * except ACES 2.0 (full) returns the same units; ACES 2.0 (full) returns\n"
   " * its limiting primaries at 1.0 = 100 nits, which dt_grade converts.\n"
   " *\n"
   " * Vulkan builds (glslang predefines VULKAN) bind at set 0, bindings 8-11. */\n"
   "#ifndef HDR_TRANSFORM_H\n"
   "#define HDR_TRANSFORM_H\n"
   "\n"
   "#ifdef VULKAN\n"
   "layout(binding = 8, std140) uniform DisplayTransform\n"
   "#else\n"
   "layout(std140) uniform DisplayTransform\n"
   "#endif\n"
   "{\n"
   "	mat3 inRgbToCam;    /* ACES 2.0 input (AP0) RGB -> CAM16 cones */\n"
   "	mat3 inConeToAab;\n"
   "	mat3 limAabToCone;\n"
   "	mat3 limCamToRgb;   /* ACES 2.0 cones -> limiting primaries */\n"
   "	mat3 aces2ToOut;    /* limiting primaries -> Rec.2020 container */\n"
   "	vec4 mode;          /* curve, H = peak/paper, hue preservation, expansion */\n"
   "	vec4 sh;            /* shoulder A, its slope, GT normalisation, AgX punchy */\n"
   "	vec4 gt;            /* GT toe m, S0, 1 - S1, C2 */\n"
   "	vec4 film;          /* Filmic Log rescale, Filmic Log norm, expansion knee, ACES 2.0 exposure */\n"
   "	vec4 inScalars;     /* F_L_n, cz, inv_cz, A_w_J */\n"
   "	vec4 limScalars;\n"
   "	vec4 ts;            /* m_2, s_2, g, t_1 */\n"
   "	vec4 cc;            /* limit_J_max, model_gamma_inv, sat, sat_thr */\n"
   "	vec4 cc2;           /* compr, chroma compress scale, mid_J, focus_dist */\n"
   "	vec4 gm;            /* lower hull gamma inv, forward limit, unused, unused */\n"
   "	vec4 lutScale;      /* cusp J, cusp M, reach M, upper hull gamma inv */\n"
   "} dt;\n"
   "\n"
   "#ifdef VULKAN\n"
   "uniform sampler2D uDtAces2Lut;\n"
   "uniform sampler2D uDtFilmLut;\n"
   "uniform sampler2D uDtFilmDesat;\n"
   "#else\n"
   "uniform highp sampler2D uDtAces2Lut;\n"
   "uniform highp sampler2D uDtFilmLut;\n"
   "uniform highp sampler2D uDtFilmDesat;\n"
   "#endif\n"
   "\n"
   "/* Curves without headroom of their own are used up to paper white and\n"
   " * carried on to H by a shoulder joined at their slope there. */\n"
   "highp float dt_shoulder(highp float v, highp float base)\n"
   "{\n"
   "	highp float e;\n"
   "	if (v <= 1.0)\n"
   "		return base;\n"
   "	e = v - 1.0;\n"
   "	return 1.0 + e * dt.sh.x * dt.sh.y / (e + dt.sh.x);\n"
   "}\n"
   "\n"
   "/* ---- ACES 2.0 output transform (Hellwig2022 JMh) ---- */\n"
   "highp float dt_cone_fwd(highp float v)\n"
   "{\n"
   "	highp float f = pow(abs(v), 0.42);\n"
   "	highp float r = f / (27.13 + f);\n"
   "	return v < 0.0 ? -r : r;\n"
   "}\n"
   "\n"
   "highp float dt_cone_inv(highp float v)\n"
   "{\n"
   "	highp float a = min(abs(v), 0.99);\n"
   "	highp float r = pow((27.13 * a) / (1.0 - a), 1.0 / 0.42);\n"
   "	return v < 0.0 ? -r : r;\n"
   "}\n"
   "\n"
   "highp vec3 dt_rgb_to_jmh(highp vec3 rgb, highp mat3 to_cam, highp mat3 cone_to_aab, highp vec4 sc)\n"
   "{\n"
   "	highp vec3 m   = to_cam * rgb;\n"
   "	highp vec3 aab = cone_to_aab * vec3(dt_cone_fwd(m.x), dt_cone_fwd(m.y), dt_cone_fwd(m.z));\n"
   "	highp float h;\n"
   "	if (aab.x <= 0.0)\n"
   "		return vec3(0.0);\n"
   "	h = degrees(atan(aab.z, aab.y));\n"
   "	if (h < 0.0)\n"
   "		h += 360.0;\n"
   "	return vec3(100.0 * pow(aab.x, sc.y), length(aab.yz), h);\n"
   "}\n"
   "\n"
   "highp vec3 dt_jmh_to_rgb(highp vec3 jmh, highp mat3 aab_to_cone, highp mat3 to_rgb, highp vec4 sc)\n"
   "{\n"
   "	highp float hr  = radians(jmh.z);\n"
   "	highp vec3  aab = vec3(pow(jmh.x * 0.01, sc.z), jmh.y * cos(hr), jmh.y * sin(hr));\n"
   "	highp vec3  a   = aab_to_cone * aab;\n"
   "	return to_rgb * vec3(dt_cone_inv(a.x), dt_cone_inv(a.y), dt_cone_inv(a.z));\n"
   "}\n"
   "\n"
   "highp float dt_j_to_y(highp float J, highp vec4 sc)\n"
   "{\n"
   "	return dt_cone_inv(sc.w * pow(abs(J) * 0.01, sc.z)) / sc.x;\n"
   "}\n"
   "\n"
   "highp float dt_y_to_j(highp float Y, highp vec4 sc)\n"
   "{\n"
   "	highp float J = 100.0 * pow(dt_cone_fwd(abs(Y) * sc.x) / sc.w, sc.y);\n"
   "	return Y < 0.0 ? -J : J;\n"
   "}\n"
   "\n"
   "highp float dt_ts_fwd(highp float x)\n"
   "{\n"
   "	highp float f = dt.ts.x * pow(max(x, 0.0) / (x + dt.ts.y), dt.ts.z);\n"
   "	return max(f * f / (f + dt.ts.w), 0.0) * 100.0;\n"
   "}\n"
   "\n"
   "highp float dt_cc_norm(highp float h)\n"
   "{\n"
   "	highp float hr = radians(h);\n"
   "	highp float a = cos(hr), b = sin(hr);\n"
   "	highp float c2 = a * a - b * b, s2 = 2.0 * a * b;\n"
   "	highp float c3 = 4.0 * a * a * a - 3.0 * a, s3 = 3.0 * b - 4.0 * b * b * b;\n"
   "	return (11.34072 * a + 16.46899 * c2 + 7.88380 * c3 + 14.66441 * b\n"
   "	        - 6.37224 * s2 + 9.19364 * s3 + 77.12896) * dt.cc2.y;\n"
   "}\n"
   "\n"
   "highp float dt_toe_fwd(highp float x, highp float limit, highp float k1in, highp float k2in)\n"
   "{\n"
   "	highp float k2, k1, k3, mb, mc;\n"
   "	if (x > limit)\n"
   "		return x;\n"
   "	k2 = max(k2in, 0.001);\n"
   "	k1 = sqrt(k1in * k1in + k2 * k2);\n"
   "	k3 = (limit + k1) / (limit + k2);\n"
   "	mb = k3 * x - k1;\n"
   "	mc = k2 * k3 * x;\n"
   "	return 0.5 * (mb + sqrt(mb * mb + 4.0 * mc));\n"
   "}\n"
   "\n"
   "highp vec4 dt_lut_at(highp float h)\n"
   "{\n"
   "	highp float u = (mod(h, 360.0) + 0.5) / 360.0;\n"
   "	return texture(uDtAces2Lut, vec2(u, 0.5)) * dt.lutScale;\n"
   "}\n"
   "\n"
   "highp vec3 dt_chroma_compress(highp vec3 jmh, highp float tmJ, highp vec4 lut)\n"
   "{\n"
   "	highp float nJ, snJ, Mn, limit, M;\n"
   "	if (jmh.y == 0.0)\n"
   "		return vec3(tmJ, 0.0, jmh.z);\n"
   "	nJ    = tmJ / dt.cc.x;\n"
   "	snJ   = max(0.0, 1.0 - nJ);\n"
   "	Mn    = dt_cc_norm(jmh.z);\n"
   "	limit = pow(nJ, dt.cc.y) * lut.z / Mn;\n"
   "	M     = jmh.y * pow(tmJ / jmh.x, dt.cc.y) / Mn;\n"
   "	M     = limit - dt_toe_fwd(limit - M, limit - 0.001, snJ * dt.cc.z, sqrt(nJ * nJ + dt.cc.w));\n"
   "	M     = dt_toe_fwd(M, limit, nJ * dt.cc2.x, snJ);\n"
   "	return vec3(tmJ, M * Mn, jmh.z);\n"
   "}\n"
   "\n"
   "highp float dt_focus_gain(highp float J, highp float athr)\n"
   "{\n"
   "	highp float gain = dt.cc.x * dt.cc2.w;\n"
   "	if (J > athr)\n"
   "	{\n"
   "		highp float adj = log(max(dt.cc.x - athr, 1e-6) / max(dt.cc.x - J, 0.0001)) / log(10.0);\n"
   "		gain *= adj * adj + 1.0;\n"
   "	}\n"
   "	return gain;\n"
   "}\n"
   "\n"
   "highp float dt_solve_j(highp float J, highp float M, highp float fJ, highp float sg)\n"
   "{\n"
   "	highp float Ms = M / sg, a = Ms / fJ, b, c;\n"
   "	if (J < fJ)\n"
   "	{\n"
   "		b = 1.0 - Ms;\n"
   "		c = -J;\n"
   "		return -2.0 * c / (b + sqrt(b * b - 4.0 * a * c));\n"
   "	}\n"
   "	b = -(1.0 + Ms + dt.cc.x * a);\n"
   "	c = dt.cc.x * Ms + J;\n"
   "	return -2.0 * c / (b - sqrt(b * b - 4.0 * a * c));\n"
   "}\n"
   "\n"
   "highp float dt_vec_slope(highp float iJ, highp float fJ, highp float sg)\n"
   "{\n"
   "	highp float d = (iJ < fJ) ? iJ : (dt.cc.x - iJ);\n"
   "	return d * (iJ - fJ) / (fJ * sg);\n"
   "}\n"
   "\n"
   "highp float dt_smin(highp float a, highp float b, highp float ref)\n"
   "{\n"
   "	highp float s  = 0.12 * ref;\n"
   "	highp float hh = max(s - abs(a - b), 0.0) / s;\n"
   "	return min(a, b) - hh * hh * hh * s / 6.0;\n"
   "}\n"
   "\n"
   "highp float dt_bound_m(highp float iJ, highp float slope, highp float ig,\n"
   "                       highp float Jm, highp float Mm, highp float Jr)\n"
   "{\n"
   "	return Jr * pow(iJ / Jr, ig) * Mm / (Jm - slope * Mm);\n"
   "}\n"
   "\n"
   "highp vec3 dt_gamut_compress(highp vec3 jmh, highp vec4 lut)\n"
   "{\n"
   "	highp float blend, fJ, athr, sg, iJ, slope, iJc, lower, upper, gb, rb, prop, thr, M;\n"
   "	if (jmh.x <= 0.0)\n"
   "		return vec3(0.0, 0.0, jmh.z);\n"
   "	if (jmh.y < 0.0 || jmh.x > dt.cc.x)\n"
   "		return vec3(jmh.x, 0.0, jmh.z);\n"
   "	blend = min(1.3 - lut.x / dt.cc.x, 1.0);\n"
   "	fJ    = lut.x + (dt.cc2.z - lut.x) * blend;\n"
   "	athr  = lut.x + (dt.cc.x - lut.x) * 0.3;\n"
   "	sg    = dt_focus_gain(jmh.x, athr);\n"
   "	iJ    = dt_solve_j(jmh.x, jmh.y, fJ, sg);\n"
   "	slope = dt_vec_slope(iJ, fJ, sg);\n"
   "	iJc   = dt_solve_j(lut.x, lut.y, fJ, sg);\n"
   "	lower = dt_bound_m(iJ, slope, dt.gm.x, lut.x, lut.y, iJc);\n"
   "	upper = dt_bound_m(dt.cc.x - iJ, -slope, lut.w, dt.cc.x - lut.x, lut.y, dt.cc.x - iJc);\n"
   "	gb    = dt_smin(lower, upper, lut.y);\n"
   "	if (gb <= 0.0)\n"
   "		return vec3(jmh.x, 0.0, jmh.z);\n"
   "	rb    = dt_bound_m(iJ, slope, dt.cc.y, dt.cc.x, lut.z, dt.cc.x);\n"
   "	prop  = max(gb / rb, 0.75);\n"
   "	thr   = prop * gb;\n"
   "	M     = jmh.y;\n"
   "	if (!(M <= thr || prop >= 1.0))\n"
   "	{\n"
   "		highp float mo = M - thr, go = gb - thr, ro = rb - thr;\n"
   "		highp float scale = ro / ((ro / go) - 1.0);\n"
   "		highp float nd = mo / scale;\n"
   "		M = thr + scale * nd / (1.0 + nd);\n"
   "	}\n"
   "	return vec3(iJ + M * slope, M, jmh.z);\n"
   "}\n"
   "\n"
   "/* Rec.709 (D65) linear -> ACES2065-1 (AP0, D60), Bradford adapted: the\n"
   " * transform's input space. Column-major. */\n"
   "const highp mat3 DT_709_TO_AP0 = mat3(\n"
   "	0.4397010, 0.0897923, 0.0175440,\n"
   "	0.3829780, 0.8134230, 0.1115440,\n"
   "	0.1773350, 0.0967616, 0.8707040);\n"
   "\n"
   "highp vec3 dt_clamp_ap0_to_ap1(highp vec3 aces, highp float upper)\n"
   "{\n"
   "	const highp mat3 to_ap1 = mat3( 1.4514393161, -0.0765537733,  0.0083161484,\n"
   "	                               -0.2365107469,  1.1762296998, -0.0060324498,\n"
   "	                               -0.2149285693, -0.0996759265,  0.9977163014);\n"
   "	const highp mat3 to_ap0 = mat3( 0.6954522414,  0.0447945634, -0.0055258826,\n"
   "	                                0.1406786965,  0.8596711185,  0.0040252103,\n"
   "	                                0.1638690622,  0.0955343182,  1.0015006723);\n"
   "	return to_ap0 * clamp(to_ap1 * aces, 0.0, upper);\n"
   "}\n"
   "\n"
   "/* Scene Rec.709 (1.0 = paper white) -> limiting primaries (1.0 = 100 nits). */\n"
   "highp vec3 dt_aces2(highp vec3 v)\n"
   "{\n"
   "	highp vec3  aces = dt_clamp_ap0_to_ap1(DT_709_TO_AP0 * v * dt.film.w, dt.gm.y);\n"
   "	highp vec3  jmh  = dt_rgb_to_jmh(aces, dt.inRgbToCam, dt.inConeToAab, dt.inScalars);\n"
   "	highp float tmJ  = dt_y_to_j(dt_ts_fwd(dt_j_to_y(jmh.x, dt.inScalars) * 0.01), dt.inScalars);\n"
   "	highp vec3  tm   = dt_chroma_compress(jmh, tmJ, dt_lut_at(jmh.z));\n"
   "	highp vec3  cg   = dt_gamut_compress(tm, dt_lut_at(tm.z));\n"
   "	return dt_jmh_to_rgb(cg, dt.limAabToCone, dt.limCamToRgb, dt.limScalars);\n"
   "}\n"
   "\n"
   "/* ---- the curves on the whole colour ---- */\n"
   "highp vec3 dt_aces_fit_rrt(highp vec3 v)\n"
   "{\n"
   "	highp vec3 a = v * (v + 0.0245786) - 0.000090537;\n"
   "	highp vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081;\n"
   "	return a / b;\n"
   "}\n"
   "\n"
   "highp vec3 dt_curve_rgb(highp vec3 c)\n"
   "{\n"
   "	int m = int(dt.mode.x + 0.5);\n"
   "	if (m == 22)        /* AgX */\n"
   "	{\n"
   "		const highp mat3 mi = mat3(0.842479062253094, 0.0784335999999992, 0.0792237451477643,\n"
   "		                           0.0423282422610123, 0.878468636469772, 0.0791661274605434,\n"
   "		                           0.0423756549057051, 0.0784336, 0.879142973793104);\n"
   "		const highp mat3 mo = mat3(1.19687900512017, -0.0980208811401368, -0.0990297440797205,\n"
   "		                           -0.0528968517574562, 1.15190312990417, -0.0989611768448433,\n"
   "		                           -0.0529716355144438, -0.0980434501171241, 1.15107367264116);\n"
   "		highp vec3 v = mi * max(c, vec3(0.0));\n"
   "		highp vec3 v2, v4;\n"
   "		v  = clamp((log2(max(v, vec3(1e-10))) + 12.47393) / 16.500009, 0.0, 1.0);\n"
   "		v2 = v * v;\n"
   "		v4 = v2 * v2;\n"
   "		v  = 15.5 * v4 * v2 - 40.14 * v4 * v + 31.96 * v4\n"
   "		   - 6.868 * v2 * v + 0.4298 * v2 + 0.1191 * v - 0.00232;\n"
   "		v  = pow(max(mo * v, vec3(0.0)), vec3(2.2)) * 1.4491792;\n"
   "		if (dt.sh.w > 0.5)  /* Punchy: contrast 1.35, saturation 1.4 */\n"
   "		{\n"
   "			highp vec3  u = pow(v, vec3(1.35));\n"
   "			highp float n = dot(u, vec3(0.2126, 0.7152, 0.0722));\n"
   "			v = max(vec3(n) + (u - vec3(n)) * 1.4, vec3(0.0));\n"
   "		}\n"
   "		return v;\n"
   "	}\n"
   "	if (m == 21)        /* Khronos PBR Neutral */\n"
   "	{\n"
   "		highp float x   = min(c.r, min(c.g, c.b));\n"
   "		highp float off = x < 0.08 ? x - 6.25 * x * x : 0.04;\n"
   "		highp vec3  v   = c - off;\n"
   "		highp float peak = max(v.r, max(v.g, v.b));\n"
   "		highp float d, np, g;\n"
   "		if (peak < 0.76)\n"
   "			return v * 1.1506276;\n"
   "		d  = 1.0 - 0.76;\n"
   "		np = 1.0 - d * d / (peak + d - 0.76);\n"
   "		v *= np / peak;\n"
   "		g  = 1.0 - 1.0 / (0.15 * (peak - np) + 1.0);\n"
   "		return mix(v, vec3(np), g) * 1.1506276;\n"
   "	}\n"
   "	if (m == 18)        /* Filmic Log (Sobotka): desaturation cube, contrast curve */\n"
   "	{\n"
   "		highp vec3  t = clamp((log2(max(c, vec3(1e-10))) + 12.4739312) * 0.04, 0.0, 1.0);\n"
   "		highp vec3  d = t * 32.0;\n"
   "		highp float bz = floor(d.z), fz = d.z - bz;\n"
   "		highp vec2  uv = vec2((bz * 33.0 + min(d.x, 31.999) + 0.5) / 1089.0, (d.y + 0.5) / 33.0);\n"
   "		highp vec3  s0 = texture(uDtFilmDesat, uv).rgb;\n"
   "		highp vec3  s1 = texture(uDtFilmDesat, uv + vec2(33.0 / 1089.0, 0.0)).rgb;\n"
   "		highp vec3  o;\n"
   "		t   = clamp(mix(s0, s1, fz) * dt.film.x, 0.0, 1.0);\n"
   "		o.r = texture(uDtFilmLut, vec2(t.r, 0.5)).r;\n"
   "		o.g = texture(uDtFilmLut, vec2(t.g, 0.5)).r;\n"
   "		o.b = texture(uDtFilmLut, vec2(t.b, 0.5)).r;\n"
   "		return pow(max(o, vec3(0.0)), vec3(2.2)) * dt.film.y;\n"
   "	}\n"
   "	if (m == 20)        /* ACES Fitted (Hill) */\n"
   "	{\n"
   "		const highp mat3 mi = mat3(0.59719, 0.07600, 0.02840,\n"
   "		                           0.35458, 0.90834, 0.13383,\n"
   "		                           0.04823, 0.01566, 0.83777);\n"
   "		const highp mat3 mo = mat3( 1.60475, -0.10208, -0.00327,\n"
   "		                           -0.53108,  1.10813, -0.07276,\n"
   "		                           -0.07367, -0.00605,  1.07602);\n"
   "		return max(mo * dt_aces_fit_rrt(mi * c), vec3(0.0)) * 1.6152077;\n"
   "	}\n"
   "	{                   /* 19: Reinhard-Jodie */\n"
   "		highp float l  = dot(c, vec3(0.2126, 0.7152, 0.0722));\n"
   "		highp vec3  tv = c / (1.0 + c);\n"
   "		return mix(c / (1.0 + l), tv, tv) * 2.0;\n"
   "	}\n"
   "}\n"
   "\n"
   "/* ---- the per-channel curves ---- */\n"
   "highp float dt_curve(highp float v)\n"
   "{\n"
   "	int m = int(dt.mode.x + 0.5);\n"
   "	highp float x = max(v, 0.0);\n"
   "	if (m == 1)         /* ACES (Narkowicz) */\n"
   "		return dt_shoulder(v, v * (2.51 * v + 0.03) / (v * (2.43 * v + 0.59) + 0.14) * 1.2440945);\n"
   "	if (m == 2)         /* Hejl and Burgess-Dawson */\n"
   "	{\n"
   "		highp float h = max(v - 0.004, 0.0);\n"
   "		return dt_shoulder(v, pow((h * (6.2 * h + 0.5)) / (h * (6.2 * h + 1.7) + 0.06), 2.2) * 1.4629683);\n"
   "	}\n"
   "	if (m == 3)         /* GT (Uchimura) */\n"
   "	{\n"
   "		highp float t  = clamp(v / dt.gt.x, 0.0, 1.0);\n"
   "		highp float w0 = 1.0 - (t * t * (3.0 - 2.0 * t));\n"
   "		highp float w2 = step(dt.gt.y, v);\n"
   "		highp float w1 = 1.0 - w0 - w2;\n"
   "		highp float T  = dt.gt.x * pow(x / dt.gt.x, 1.33);\n"
   "		highp float S  = 1.0 - dt.gt.z * exp(-dt.gt.w * (v - dt.gt.y));\n"
   "		return (T * w0 + v * w1 + S * w2) * dt.sh.z;\n"
   "	}\n"
   "	if (m == 4)         /* Hable (Uncharted 2) */\n"
   "		return dt_shoulder(v, (((v * (0.15 * v + 0.05) + 0.004) / (v * (0.15 * v + 0.50) + 0.06))\n"
   "		                       - 0.0666667) * 4.5319149);\n"
   "	if (m == 5)         /* Lottes */\n"
   "		return dt_shoulder(v, (pow(x, 1.6) / (pow(x, 1.5632) * 0.1674199 + 1.0730397)) * 1.2404596);\n"
   "	if (m == 6)         /* Drago */\n"
   "		return dt_shoulder(v, log(1.0 + x) / log(2.0 + 8.0 * pow(x / 8.0, 0.2344653))\n"
   "		                      * (1.0 / 0.9542425) * 2.6616800);\n"
   "	if (m == 7)         /* Unreal */\n"
   "		return dt_shoulder(v, pow(v / (v + 0.155) * 1.019, 2.2) * 1.3173380);\n"
   "	if (m == 8)         /* Filmic ALU (Hejl 2015) */\n"
   "	{\n"
   "		highp float va = 1.425 * x + 0.05;\n"
   "		highp float f  = ((x * va + 0.004) / ((x * va + 0.055) + 0.0491)) - 0.0821;\n"
   "		return dt_shoulder(v, pow(max(f, 0.0), 2.2) * 1.4132626);\n"
   "	}\n"
   "	if (m == 9)         /* Reinhard (plain) */\n"
   "		return dt_shoulder(v, (x / (1.0 + x)) * 2.0);\n"
   "	if (m == 10)        /* Reinhard (extended, white 4) */\n"
   "		return dt_shoulder(v, (x * (1.0 + x / 16.0) / (1.0 + x)) * 1.8823529);\n"
   "	if (m == 11)        /* Exponential */\n"
   "		return dt_shoulder(v, (1.0 - exp(-x)) * 1.5819767);\n"
   "	if (m == 12)        /* Hable 2017 piecewise */\n"
   "	{\n"
   "		highp float f;\n"
   "		if (x < 0.25)\n"
   "			f = 1.1313708 * pow(x, 1.25);\n"
   "		else if (x < 0.70)\n"
   "			f = 0.20 + (x - 0.25);\n"
   "		else\n"
   "			f = 0.65 + 0.35 * (x - 0.70) / ((x - 0.70) + 0.35);\n"
   "		return dt_shoulder(v, f * 1.2322275);\n"
   "	}\n"
   "	if (m == 13)        /* ACES 2.0 tone scale alone */\n"
   "	{\n"
   "		highp float f = 1.0471038 * pow(x / (x + 0.9198583), 1.15);\n"
   "		return dt_shoulder(v, (f * f / (f + 0.04)) * 2.1854781);\n"
   "	}\n"
   "	if (m == 14)        /* Tumblin-Rushmeier */\n"
   "		return dt_shoulder(v, pow(x, 0.6075));\n"
   "	if (m == 15)        /* Ward */\n"
   "		return dt_shoulder(v, x);\n"
   "	if (m == 16)        /* Schlick */\n"
   "		return dt_shoulder(v, 2.3 * x / (2.3 * x - x + 1.0));\n"
   "	/* 17: Reinhard-Devlin */\n"
   "	return dt_shoulder(v, (x / (x + 0.3010864)) * 1.3010864);\n"
   "}\n"
   "\n"
   "/* HDR Expansion: lifts the top of the range into the headroom. */\n"
   "highp vec3 dt_expand_curve(highp vec3 v, highp float E, highp float K)\n"
   "{\n"
   "	highp vec3 t  = clamp((v - K) / max(1.0 - K, 1e-4), 0.0, 1.0);\n"
   "	highp vec3 hi = K + (1.0 - K) * t + (E - 1.0) * t * t + max(v - 1.0, 0.0);\n"
   "	return mix(v, hi, step(vec3(K), v));\n"
   "}\n"
   "\n"
   "highp vec3 dt_expand(highp vec3 c)\n"
   "{\n"
   "	highp float E = dt.mode.y, p;\n"
   "	if (dt.mode.w < 0.5 || E <= 1.0001)\n"
   "		return c;\n"
   "	if (dt.mode.w < 1.5)\n"
   "		return dt_expand_curve(c, E, dt.film.z);\n"
   "	p = max(c.r, max(c.g, c.b));\n"
   "	if (p <= 1e-5)\n"
   "		return c;\n"
   "	return c * (dt_expand_curve(vec3(p), E, dt.film.z).x / p);\n"
   "}\n"
   "\n"
   "/* Scene Rec.709 (1.0 = paper white) -> Rec.709 in paper-white units, or,\n"
   " * for ACES 2.0 (full), Rec.2020 nits; `absolute` tells the caller which. */\n"
   "highp vec3 dt_apply(highp vec3 v, highp float paper_white_nits, out bool absolute)\n"
   "{\n"
   "	highp float pre;\n"
   "	int m = int(dt.mode.x + 0.5);\n"
   "	v = dt_expand(max(v, vec3(0.0)));\n"
   "	absolute = (m == 23);\n"
   "	if (absolute)\n"
   "		return dt.aces2ToOut * dt_aces2(v) * 100.0;\n"
   "	pre = max(v.r, max(v.g, v.b));\n"
   "	if (m >= 18)\n"
   "		v = dt_curve_rgb(v);\n"
   "	else\n"
   "		v = vec3(dt_curve(v.r), dt_curve(v.g), dt_curve(v.b));\n"
   "	if (dt.mode.z > 0.5)   /* Highlight Hue Preservation */\n"
   "	{\n"
   "		highp float post = max(v.r, max(v.g, v.b));\n"
   "		highp float g    = 1.0 - 1.0 / (0.15 * max(pre - post, 0.0) + 1.0);\n"
   "		v = mix(v, vec3(post), g);\n"
   "	}\n"
   "	return v;\n"
   "}\n"
   "\n"
   "#endif /* HDR_TRANSFORM_H */\n"
   "/* ---- end hdr_transform.h ---- */\n"
   "#endif\n"
   "\n"
   "/* The grade both HDR outputs share: linear light in, absolute nits out, in\n"
   " * the Rec.2020 container after the Colour Boost rotation and panel gamut\n"
   " * compression. `scene_linear` is normalised with 1.0 at reference white;\n"
   " * values above that are the additive overshoot the roll-off compresses. */\n"
   "highp vec3 hdr_grade_linear(highp vec3 scene_linear, highp float paper_white_nits,\n"
   "                            highp float peak_nits, int expand_gamut, int shoulder,\n"
   "                            int src_primaries, highp mat3 to_panel)\n"
   "{\n"
   "	/* STEP 3: one transfer function across the whole range, then compress\n"
   "	 * whatever lands above paper white.\n"
   "	 *\n"
   "	 * The signal is PSX-native and gamma-encoded; sdr_to_linear is the\n"
   "	 * display transfer (defaulting to the pure 2.4 RetroArch uses in its own\n"
   "	 * Vulkan/D3D HDR shaders). Applying it to the whole value - including the >1.0 left in the 16F\n"
   "	 * framebuffer by additive blends - is what keeps the encode continuous.\n"
   "	 * Decoding only [0,1] and treating the overshoot as if it were already\n"
   "	 * linear light mixes two domains in one sum, and the slope then steps by\n"
   "	 * headroom/(2.4*paper_white) - 1.67x at 200/1000 nits - exactly at\n"
   "	 * reference white, which contours any gradient that crosses it and makes\n"
   "	 * the deband grain visibly coarsen at the same threshold.\n"
   "	 *\n"
   "	 * Content in [0,1] is untouched by this: the transfer maps 1.0 to 1.0 for\n"
   "	 * every sdr_eotf, so sdr_to_linear(c)*paper_white <= paper white, so the roll-off below never engages and the standard range still\n"
   "	 * maps bit-for-bit onto the SDR result.\n"
   "	 *\n"
   "	 * The knee is driven by the peak (brightest) overshoot channel and the\n"
   "	 * overshoot is scaled proportionally, rather than kneeing each channel on\n"
   "	 * its own: a per-channel roll-off compresses the brightest channel hardest,\n"
   "	 * which desaturates a hot coloured highlight toward white (a saturated\n"
   "	 * additive red would wash out as it brightens). Scaling by the shared\n"
   "	 * factor keeps the overshoot's chromaticity, so a hot additive red stays\n"
   "	 * red. Dim channels are left alone, as before. */\n"
   "	/* peak_nits is what the display can actually reach, supplied by the\n"
   "	 * frontend as GET_HDR_METADATA max_nits. Everything above paper white and\n"
   "	 * below it is the headroom available for highlights, so a wrong value is\n"
   "	 * either wasted range or clipping - which is why this stopped being the\n"
   "	 * hardcoded 1000 it was.\n"
   "	 *\n"
   "	 * The frontend may report a peak below paper white if the user has set it\n"
   "	 * that way; headroom then clamps to zero and the roll-off degenerates to a\n"
   "	 * clamp at paper white, which is the right behaviour rather than a\n"
   "	 * negative range. */\n"
   "#ifdef HDR_DT\n"
   "	/* The Display Transform option replaces the knee below. */\n"
   "	if (dt.mode.x > 0.5)\n"
   "	{\n"
   "		bool absolute;\n"
   "		highp vec3 v = dt_apply(src_primaries_to_709(max(scene_linear, vec3(0.0)), src_primaries),\n"
   "		                        paper_white_nits, absolute);\n"
   "		if (absolute)\n"
   "			return v;\n"
   "		return panel_gamut_compress(rec709_to_target(v * paper_white_nits, expand_gamut), to_panel);\n"
   "	}\n"
   "#endif\n"
   "	highp float headroom = max(peak_nits - paper_white_nits, 0.0);\n"
   "	highp vec3  lin      = src_primaries_to_709(max(scene_linear, vec3(0.0)), src_primaries)\n"
   "	                     * paper_white_nits;\n"
   "	/* Linear-light overshoot. Forced to zero when there is no headroom\n"
   "	 * (paper white at or above the ceiling), which clamps to paper white\n"
   "	 * instead of letting the knee pass the value through unscaled. */\n"
   "	highp vec3  over     = (headroom > 0.0)\n"
   "	                          ? max(lin - vec3(paper_white_nits), vec3(0.0))\n"
   "	                          : vec3(0.0);\n"
   "	highp float omax     = max(over.r, max(over.g, over.b));\n"
   "	highp float o        = (omax > 0.0) ? (omax / headroom) : 0.0;\n"
   "	/* Per-unit-overshoot factor S(o)/o, shared across channels. shoulder\n"
   "	 * selects S: 0 = Reinhard o/(o+1) (S/o = 1/(o+1)); 1 = filmic. Both have\n"
   "	 * S'(0) == 1, so the peak channel leaves white at the same slope it\n"
   "	 * arrived with and asymptotes to the ceiling.\n"
   "	 *\n"
   "	 * (1-exp(-o))/o cancels catastrophically as o -> 0 - fp32 loses 40% of the\n"
   "	 * value by o = 1e-7, and that is precisely the neighbourhood of reference\n"
   "	 * white - so the small-o branch uses the series 1 - o/2 + o^2/6, which is\n"
   "	 * good to ~1e-7 at the crossover and exact at the origin. */\n"
   "	highp float knee     = 0.0;\n"
   "	if (o > 0.0)\n"
   "	{\n"
   "		if (shoulder == 1)\n"
   "			knee = (o < 1e-2)\n"
   "			          ? (1.0 - o * (0.5 - o * (1.0 / 6.0)))\n"
   "			          : (filmic_shoulder(o) / o);\n"
   "		else\n"
   "			knee = 1.0 / (o + 1.0);\n"
   "	}\n"
   "	lin = min(lin, vec3(paper_white_nits)) + over * knee;\n"
   "	lin = rec709_to_target(lin, expand_gamut);\n"
   "	return panel_gamut_compress(lin, to_panel);\n"
   "}\n"
   "\n"
   "/* Rec.2020 -> Rec.709, the inverse of the Accurate rotation. */\n"
   "highp vec3 rec2020_to_709(highp vec3 c)\n"
   "{\n"
   "	return vec3(\n"
   "		 1.6604903 * c.r + -0.5876391 * c.g + -0.0728516 * c.b,\n"
   "		-0.1245500 * c.r +  1.1328999 * c.g + -0.0083480 * c.b,\n"
   "		-0.0181511 * c.r + -0.1005787 * c.g +  1.1187299 * c.b);\n"
   "}\n"
   "\n"
   "/* HDR output from linear light, in the format the frontend accepted.\n"
   " *\n"
   " *   scrgb == 0  HDR10: PQ-encoded Rec.2020, with the black-floor toe in the\n"
   " *               PQ domain.\n"
   " *   scrgb != 0  RETRO_PIXEL_FORMAT_SCRGB_RGBA16F: linear Rec.709, 1.0 = 80\n"
   " *               nits. The same graded light, so the two formats present the\n"
   " *               same picture: the container rotation is undone exactly, colours\n"
   " *               outside Rec.709 are negative rather than clipped, and the toe\n"
   " *               is applied through a PQ round trip so it lands where the HDR10\n"
   " *               path puts it. That round trip runs only when a black level is\n"
   " *               known.\n"
   " *\n"
   " * scrgb comes from a push constant, so the branch is uniform. */\n"
   "highp vec3 encode_hdr_output_linear(highp vec3 scene_linear, highp float paper_white_nits,\n"
   "                                    highp float peak_nits, int expand_gamut, int shoulder,\n"
   "                                    int src_primaries, highp float black_pq,\n"
   "                                    highp mat3 to_panel, int scrgb)\n"
   "{\n"
   "	highp vec3 lin = hdr_grade_linear(scene_linear, paper_white_nits, peak_nits,\n"
   "	                                  expand_gamut, shoulder, src_primaries, to_panel);\n"
   "	if (scrgb == 0)\n"
   "		return pq_black_floor(pq_encode(lin), black_pq);\n"
   "	if (black_pq > 0.0)\n"
   "		lin = pq_decode(pq_black_floor(pq_encode(lin), black_pq));\n"
   "	return rec2020_to_709(lin) * (1.0 / 80.0);\n"
   "}\n"
   "\n"
   "highp vec3 encode_hdr_output(highp vec3 rgb, highp float paper_white_nits, highp float peak_nits,\n"
   "                             int expand_gamut, int shoulder, int sdr_eotf, int src_primaries,\n"
   "                             highp float black_pq, highp mat3 to_panel, int scrgb)\n"
   "{\n"
   "	return encode_hdr_output_linear(sdr_to_linear(max(rgb, vec3(0.0)), sdr_eotf),\n"
   "	                                paper_white_nits, peak_nits, expand_gamut, shoulder,\n"
   "	                                src_primaries, black_pq, to_panel, scrgb);\n"
   "}\n"
   "\n"
   "/* HDR post effects (bloom, halation, chromatic aberration). With\n"
   " * HDR_LINEAR_OUT set the display stage writes scene-linear light - 1.0 at\n"
   " * reference white, still in the authoring primaries - to a half-float image\n"
   " * instead of encoding, and hdr_post.frag encodes after the effects. A\n"
   " * specialization constant on Vulkan, so the default pipelines compile to the\n"
   " * code they always had; a uniform on GL. Constant 1 is the primitive\n"
   " * shaders' FILTER_TYPE slot, which no display program shares. */\n"
   "#if defined(HDR)\n"
   "#ifdef VULKAN\n"
   "layout(constant_id = 1) const int HDR_LINEAR_OUT = 0;\n"
   "#else\n"
   "uniform int HDR_LINEAR_OUT;\n"
   "#endif\n"
   "#endif\n"
   "\n"
   "/* ---- Debanding dither -----------------------------------------------------\n"
   " * For the genuinely-8-bit paths whose gradients are already quantised and\n"
   " * would band at 10-bit. ~1 8-bit-LSB of triangular-PDF noise, spatially\n"
   " * distributed with interleaved gradient noise (blue-noise-like, no texture),\n"
   " * applied in gamma space. TPDF decorrelates the noise from the signal, so it\n"
   " * reads as a faint even grain. Not for interpolated content (mipmap resolve,\n"
   " * YUV chroma) - that already carries sub-8-bit precision 10-bit preserves. */\n"
   "highp float hdr_ign(highp vec2 p, highp vec2 k)  /* IGN along direction k -> [0,1) */\n"
   "{\n"
   "	return fract(52.9829189 * fract(dot(p, k)));\n"
   "}\n"
   "\n"
   "highp float hdr_tri(highp float u)  /* uniform [0,1) -> triangular (-1,1) */\n"
   "{\n"
   "	return u < 0.5 ? sqrt(2.0 * u) - 1.0 : 1.0 - sqrt(2.0 - 2.0 * u);\n"
   "}\n"
   "\n"
   "highp vec3 hdr_deband(highp vec3 rgb, highp vec2 fragcoord)\n"
   "{\n"
   "	/* Per-channel IGN *direction* (not a shared field offset) gives three\n"
   "	 * decorrelated fields, so the grain carries no chroma tint (pairwise\n"
   "	 * channel correlation ~0). Each is remapped to a triangular PDF. */\n"
   "	highp vec3 t = vec3(\n"
   "		hdr_tri(hdr_ign(fragcoord, vec2( 0.06711056,  0.00583715))),\n"
   "		hdr_tri(hdr_ign(fragcoord, vec2( 0.00583715,  0.06711056))),\n"
   "		hdr_tri(hdr_ign(fragcoord, vec2( 0.06711056, -0.00583715))));\n"
   "	return rgb + t * (1.0 / 255.0);\n"
   "}\n"
   "\n"
   "/* Luma-only variant for the YUV FMV path. Its chroma is reconstructed at\n"
   " * sub-8-bit precision (2x2 average + bilinear) that 10-bit preserves, so it\n"
   " * must NOT be dithered; only the per-pixel 8-bit luma steps. An equal offset\n"
   " * to R,G,B is chroma-neutral through the BT.601 matrix (U,V rows sum ~0, Y\n"
   " * row 1), so one triangular sample on all channels dithers luma alone. */\n"
   "highp vec3 hdr_deband_luma(highp vec3 rgb, highp vec2 fragcoord)\n"
   "{\n"
   "	highp float t = hdr_tri(hdr_ign(fragcoord, vec2(0.06711056, 0.00583715)));\n"
   "	return rgb + vec3(t) * (1.0 / 255.0);\n"
   "}\n"
   "\n"
   "#endif /* HDR_H */\n"
   "/* ---- end hdr.h ---- */\n"
   "\n"
   "in highp vec2 vUV;\n"
   "out highp vec4 FragColor;\n"
   "\n"
   "uniform sampler2D uDecoded;\n"
   "\n"
   "uniform vec2 reg_sig_size;\n"
   "uniform vec2 reg_out_size;\n"
   "uniform int reg_sdr_eotf;\n"
   "uniform float reg_paper_white_nits;\n"
   "uniform float reg_peak_nits;\n"
   "uniform int reg_expand_gamut;\n"
   "uniform int reg_shoulder;\n"
   "uniform int reg_src_primaries;\n"
   "uniform float reg_black_pq;\n"
   "uniform int reg_scrgb;\n"
   "uniform mat3 reg_to_panel;\n"
   "\n"
   "void main()\n"
   "{\n"
   "	highp float row = vUV.y;\n"
   "\n"
   "	/* Base samples per output pixel. At 1x this is `div` and the box is the\n"
   "	 * exact inverse of the CRTC hold. Above 1x the window narrows and the\n"
   "	 * sub-native structure the cable produces - ringing, chroma smear, dot\n"
   "	 * crawl, all at base-clock rate - survives instead of averaging flat.\n"
   "	 * Below 1 the band-limited signal is simply interpolated. */\n"
   "	highp float bpo = reg_sig_size.x / max(reg_out_size.x, 1.0);\n"
   "	highp float n0  = floor(gl_FragCoord.x) * bpo;\n"
   "	highp int   num = int(clamp(floor(bpo + 0.5), 1.0, 16.0));\n"
   "\n"
   "	highp vec3  acc = vec3(0.0);\n"
   "	highp float cnt = 0.0;\n"
   "	int i;\n"
   "	for (i = 0; i < 16; i++)\n"
   "	{\n"
   "		if (i >= num)\n"
   "			break;\n"
   "		highp float k = clamp(n0 + float(i), 0.0, reg_sig_size.x - 1.0);\n"
   "		highp vec3  v = textureLod(uDecoded, vec2((k + 0.5) / reg_sig_size.x, row), 0.0).rgb;\n"
   "		acc += sdr_to_linear(clamp(v, vec3(0.0), vec3(1.0)), reg_sdr_eotf);\n"
   "		cnt += 1.0;\n"
   "	}\n"
   "\n"
   "	highp vec3 lin = acc / max(cnt, 1.0);\n"
   "\n"
   "#if defined(HDR)\n"
   "	/* encode_hdr_output_linear rotates the primaries itself. */\n"
   "	if (HDR_LINEAR_OUT != 0)\n"
   "	{\n"
   "		FragColor = vec4(lin, 1.0);\n"
   "	}\n"
   "	else\n"
   "	{\n"
   "		FragColor = vec4(encode_hdr_output_linear(lin, reg_paper_white_nits, reg_peak_nits,\n"
   "		                                          reg_expand_gamut, reg_shoulder,\n"
   "		                                          reg_src_primaries, reg_black_pq,\n"
   "		                                          reg_to_panel, reg_scrgb), 1.0);\n"
   "	}\n"
   "#else\n"
   "	/* Rotated here rather than through sdr_apply_src_primaries: this pass is\n"
   "	 * already holding linear light, so it costs a matrix and no round trip. */\n"
   "	FragColor = vec4(linear_to_sdr(src_primaries_to_709(lin, reg_src_primaries),\n"
   "	                               reg_sdr_eotf), 1.0);\n"
   "#endif\n"
   "}\n"
   ;

#endif /* GL_ANALOG_RESOLVE_GLSL_H */
